                p.fixed=integer(t[7]);p.outer=integer(t[8]);p.accounting=integer(t[9]);p.naming=integer(t[10]);p.features=integer(t[11]);p.chain_min=integer(t[12]);p.source=t[13];p.audit=t[14];
