                    mpz_mod(xj, tmul, L.N);
                    mpz_mul(iprod, iprod, zv[j]);
                    mpz_mod(iprod, iprod, L.N);
                    mpz_neg(neg, xj);
                    mpz_mod(neg, neg, L.N);
                    mpz_to_words(w, nw, neg);
                    leaf[lo + j].assign(2 * nw, 0ull);
                    std::copy(w.begin(), w.end(), leaf[lo + j].begin());
                    leaf[lo + j][nw] = 1;
                }
